    16	/** The state of a subscription after all of its events, oldest first. The first event must be the start. */
    17	export function replay(events: readonly SubscriptionEvent[]): Subscription {
    18	  const [first, ...rest] = events;
    19	  if (first?.type !== "subscription_started") {
    20	    throw new Error("A subscription history starts with subscription_started");
    21	  }
    22	  return rest.reduce(reduceSubscription, startedSubscription(first));
